<?php $singular=['users'=>'usuário','categories'=>'categoria','tickets'=>'chamado'][$page]; ?>
<form class="toolbar" method="get"><input type="hidden" name="page" value="<?= e($page) ?>"><div class="search-field search-compact"><?= icon('search') ?><input type="search" name="q" value="<?= e($search) ?>" placeholder="Pesquisar <?= e(mb_strtolower($title)) ?>..." aria-label="Pesquisar por palavra-chave"><button class="search-submit" aria-label="Pesquisar"><?= icon('arrow-right') ?></button></div><?php if($canManage): ?><a class="button" href="<?= e(url($page,['action'=>'create'])) ?>"><?= icon('plus') ?><?= $page==='categories'?'Nova categoria':'Novo '.$singular ?></a><?php endif; ?><?php if($page==='tickets'): ?><div class="filter-panel"><select name="status" aria-label="Filtrar status"><option value="">Todos os status</option><?php foreach(\App\Models\Ticket::STATUSES as $status): ?><option <?= $filters['status']===$status?'selected':'' ?>><?= e($status) ?></option><?php endforeach; ?></select><select name="priority" aria-label="Filtrar prioridade"><option value="">Todas as prioridades</option><?php foreach(\App\Models\Ticket::PRIORITIES as $priority): ?><option <?= $filters['priority']===$priority?'selected':'' ?>><?= e($priority) ?></option><?php endforeach; ?></select><select name="category" aria-label="Filtrar categoria"><option value="">Todas as categorias</option><?php foreach($categories as $category): ?><option value="<?= $category['id'] ?>" <?= (string)$category['id']===$filters['category']?'selected':'' ?>><?= e($category['name']) ?></option><?php endforeach; ?></select><button class="button button-small">Filtrar</button><a class="text-link" href="<?= e(url($page)) ?>">Limpar</a></div><?php endif; ?></form>
<section class="card"><header class="card-heading"><h3><?= e($title) ?></h3><span class="muted"><?= count($rows) ?> registro(s)</span></header><?php if(!$rows): empty_state('Nenhum '.$singular.' encontrado',$canManage?'Adicione um registro ou ajuste os termos da pesquisa.':'Os chamados vinculados a você aparecerão aqui. Se estiver pesquisando, ajuste os filtros.');else: ?><div class="table-scroll"><table><thead><tr><?php $headings=match($page){'users'=>['Usuário','E-mail','Perfil','Chamados'],'categories'=>['Categoria','Descrição','Chamados'],default=>['Chamado','Solicitante','Destinatário / responsável','Categoria','Prioridade','Status']};foreach($headings as $heading): ?><th><?= e($heading) ?></th><?php endforeach; ?><th>Ações</th></tr></thead><tbody><?php foreach($rows as $row): ?><tr>
<?php if($page==='users'): ?><td><div class="table-room"><span class="avatar small"><?= e(initials($row['name'])) ?></span><strong><?= e($row['name']) ?></strong></div></td><td><?= e($row['email']) ?></td><td><?= badge($row['role']==='Usuário'?'Professor':$row['role']) ?></td><td><?= $row['ticket_count'] ?></td>
<?php elseif($page==='categories'): ?><td><strong><?= e($row['name']) ?></strong></td><td class="description-cell"><?= e($row['description']) ?></td><td><?= $row['ticket_count'] ?></td>
<?php else: ?><td><a class="ticket-title" href="<?= e(url('tickets',['action'=>'show','id'=>$row['id']])) ?>"><small>#<?= str_pad((string)$row['id'],4,'0',STR_PAD_LEFT) ?></small><strong><?= e($row['subject']) ?></strong></a></td><td><?= e($row['user_name']) ?></td><td><?= e($row['assignee_name']??'Não atribuído') ?></td><td><?= e($row['category_name']) ?></td><td><?= badge($row['priority']) ?></td><td><?= badge($row['status']) ?></td><?php endif; ?>
<td><div class="actions"><?php if($page==='tickets'): ?><a class="icon-button" href="<?= e(url($page,['action'=>'show','id'=>$row['id']])) ?>" aria-label="Ver <?= e($row['subject']) ?>"><?= icon('eye') ?></a><?php endif; ?><?php if($canManage): ?><a class="icon-button" href="<?= e(url($page,['action'=>'edit','id'=>$row['id']])) ?>" aria-label="Editar <?= e($row['name']??$row['subject']) ?>"><?= icon('pencil') ?></a><?php delete_button($page,(int)$row['id'],$row['name']??$row['subject']); endif; ?></div></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>

